import{_ as a,o,c as t,a2 as n}from"./chunks/framework.CTx8wfac.js";const u=JSON.parse('{"title":"AI commands","description":"","frontmatter":{},"headers":[],"relativePath":"tooling/ai-commands.md","filePath":"tooling/ai-commands.md"}'),r={name:"tooling/ai-commands.md"};function d(s,e,i,c,l,g){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-commands" tabindex="-1">AI commands <a class="header-anchor" href="#ai-commands" aria-label="Permalink to &quot;AI commands&quot;">​</a></h1><p>AI is a <strong>primary axis</strong> for BananaJS—not a gimmick. Capabilities include <strong>generate</strong> from schema or prompt, <strong><code>ai generate --module</code></strong> for DDD layouts (with <strong><code>.bananarc.json</code></strong> and <strong><code>ai setup</code></strong>), <strong><code>doc</code></strong>, and <strong><code>review</code></strong> (<a href="/banana-universe/guide/philosophy.html">Philosophy</a>).</p><p>Commands live under <strong><code>bananajs ai</code></strong> (<code>packages/bananajs-cli/src/lib/ai.ts</code> and related modules).</p><h2 id="bananajs-ai-generate" tabindex="-1"><code>bananajs ai generate</code> <a class="header-anchor" href="#bananajs-ai-generate" aria-label="Permalink to &quot;`bananajs ai generate`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong><code>--from-schema &lt;file&gt;</code></strong></td><td>JSON Schema or OpenAPI file — deterministic codegen (no LLM required for basic flows)</td></tr><tr><td><strong><code>--from-prompt &lt;text&gt;</code></strong></td><td>Natural language — uses the LLM from <strong><code>.bananarc.json</code></strong> (Ollama offline by default; cloud optional)</td></tr><tr><td><strong><code>--module</code></strong></td><td>With <strong><code>--from-prompt</code></strong> or <strong><code>--from-schema</code></strong>, generates the <strong>layered DDD</strong> tree (see below)</td></tr><tr><td><strong><code>--out &lt;dir&gt;</code></strong></td><td>Output directory (default: current working directory)</td></tr><tr><td><strong><code>--dry-run</code></strong></td><td>Print generated files without writing</td></tr></tbody></table><p>Implementation details and provider matrix can change between releases — inspect <strong><code>packages/bananajs-cli</code></strong> for the current stack.</p><h2 id="bananajs-ai-doc" tabindex="-1"><code>bananajs ai doc</code> <a class="header-anchor" href="#bananajs-ai-doc" aria-label="Permalink to &quot;`bananajs ai doc`&quot;">​</a></h2><p>Adds JSDoc to controller methods using the configured LLM.</p><ul><li><strong><code>--file &lt;path&gt;</code></strong> — single file; otherwise scans project <code>src/</code></li><li><strong><code>--dry-run</code></strong></li></ul><h2 id="bananajs-ai-review" tabindex="-1"><code>bananajs ai review</code> <a class="header-anchor" href="#bananajs-ai-review" aria-label="Permalink to &quot;`bananajs ai review`&quot;">​</a></h2><p>Reviews a controller for BananaJS best practices.</p><ul><li><strong><code>--file &lt;path&gt;</code></strong> — required target file</li></ul><h2 id="bananajs-ai-setup" tabindex="-1"><code>bananajs ai setup</code> <a class="header-anchor" href="#bananajs-ai-setup" aria-label="Permalink to &quot;`bananajs ai setup`&quot;">​</a></h2><p>Interactive wizard that writes <strong><code>.bananarc.json</code></strong> (LLM provider, defaults for <strong><code>ai generate --module</code></strong>). See <strong><a href="/banana-universe/tooling/ai-module-generation.html">AI module generation</a></strong> for the full walkthrough.</p><h2 id="ddd-module-generation" tabindex="-1">DDD module generation <a class="header-anchor" href="#ddd-module-generation" aria-label="Permalink to &quot;DDD module generation&quot;">​</a></h2><p><strong><code>bananajs ai generate --module</code></strong> uses the <strong><code>llm/</code></strong> provider layer, Zod-validated extraction, and embedded templates for domain / application / infrastructure folders. Full walkthrough: <strong><a href="/banana-universe/tooling/ai-module-generation.html">AI module generation</a></strong>.</p>',16)])])}const h=a(r,[["render",d]]);export{u as __pageData,h as default};
